function friendlyHttp(status,d,isJson,path){if(d&&d.error)return `${d.error}${d.requestId?` (ref ${d.requestId})`:''}`;const host=API||location.origin;if(!isJson&&native()&&!API)return `${APK_NO_API} The app called ${path} and received HTTP ${status} from its own local server.`;if(!isJson)return `${host}${path} returned HTTP ${status} with a non-JSON page. The API may not be deployed at this address. Open ${host}/api/health to check.`;if(status===401)return 'Your session is missing or expired. Sign in again.';if(status===404)return `API route not found: ${path}. The deployed API may be older than this app build.`;if(status===405)return `Method not allowed at ${path}. The request reached a server that does not run Pothub's API.`;if(status>=500)return `Pothub server error (HTTP ${status}) at ${path}. Use the reference ID when checking the Vercel logs.`;return `Request to ${path} failed with HTTP ${status}.`}
