async function api(path,opts={}){const {timeoutMs:requestTimeout=25000,noRetry=false,idempotencyKey,...fetchOptions}=opts,method=String(fetchOptions.method||'GET').toUpperCase(),retryable=!noRetry&&(['GET','HEAD'].includes(method)||!!idempotencyKey);let attempt=0;while(true){const ctrl=new AbortController(),t=setTimeout(()=>ctrl.abort(),requestTimeout);try{let bearer=nativeSessionToken;try{if(!native())bearer=sessionStorage.getItem('pothub-session-v1')||''}catch{}const headers={'Content-Type':'application/json',...(bearer?{Authorization:`Bearer ${bearer}`}:{ }),...(fetchOptions.headers||{})};if(idempotencyKey)headers['Idempotency-Key']=idempotencyKey;const r=await fetch(`${API}${path}`,{credentials:'include',...fetchOptions,headers,signal:ctrl.signal});const isJson=(r.headers.get('content-type')||'').includes('application/json');const d=isJson?await r.json().catch(()=>({})):{};if(!r.ok)throw Object.assign(new Error(friendlyHttp(r.status,d,isJson,path)),{status:r.status,code:d.code||`HTTP_${r.status}`,requestId:d.requestId||r.headers.get('x-request-id')||null});return d;}catch(e){if(retryable&&attempt<2&&(!e.status||e.status>=500)){await new Promise(r=>setTimeout(r,350*Math.pow(2,attempt++)));continue}if(e.status)throw e;throw Object.assign(new Error(friendlyNetwork(e,path,requestTimeout)),{code:e.name==='AbortError'?'TIMEOUT':'NETWORK'})}finally{clearTimeout(t)}}}



