function BlobVideo({blob}){const [url,setUrl]=useState(''),[poster,setPoster]=useState('');useEffect(()=>{if(!blob)return;const next=URL.createObjectURL(blob);setUrl(next);setPoster('');return()=>URL.revokeObjectURL(next)},[blob]);return url?<video controls playsInline src={url} poster={poster||undefined} onLoadedData={e=>{try{const v=e.currentTarget,c=document.createElement('canvas');c.width=Math.min(640,v.videoWidth||640);c.height=Math.max(1,Math.round(c.width*(v.videoHeight||360)/(v.videoWidth||640)));c.getContext('2d')?.drawImage(v,0,0,c.width,c.height);setPoster(c.toDataURL('image/jpeg',.72))}catch{}}}/>:null}

function Particles(){useEffect(()=>{const c=document.querySelector('#particles'),ctx=c?.getContext('2d');if(!ctx)return;let w,h,raf,pts=[],hidden=document.hidden;const resize=()=>{w=c.width=innerWidth*devicePixelRatio;h=c.height=innerHeight*devicePixelRatio;c.style.width=innerWidth+'px';c.style.height=innerHeight+'px';pts=Array.from({length:Math.min(75,Math.floor(innerWidth/14))},()=>({x:Math.random()*w,y:Math.random()*h,vx:(Math.random()-.5)*.18,vy:(Math.random()-.5)*.18,r:Math.random()*1.5+.5}));};const draw=()=>{if(hidden||matchMedia('(prefers-reduced-motion: reduce)').matches)return;ctx.clearRect(0,0,w,h);ctx.fillStyle='rgba(150,170,190,.7)';for(const p of pts){p.x+=p.vx*devicePixelRatio;p.y+=p.vy*devicePixelRatio;if(p.x<0||p.x>w)p.vx*=-1;if(p.y<0||p.y>h)p.vy*=-1;ctx.beginPath();ctx.arc(p.x,p.y,p.r*devicePixelRatio,0,Math.PI*2);ctx.fill()}raf=requestAnimationFrame(draw)};const vis=()=>{hidden=document.hidden;if(!hidden)draw();else cancelAnimationFrame(raf)};resize();draw();addEventListener('resize',resize);document.addEventListener('visibilitychange',vis);return()=>{cancelAnimationFrame(raf);removeEventListener('resize',resize);document.removeEventListener('visibilitychange',vis)}},[]);return <canvas id="particles" aria-hidden="true"/>}
